(4972229, 724471, 97760, '<td valign="top">love it!</td>', 'love it!', '2008-09-24 12:28:47.000000', NULL, 1),
(4972242, 723081, 30982, '<td valign="top">Conveys red to me.  And I suspect the ribbon is yellow, the bushes behind a nice deep green.</td>', 'Conveys red to me.  And I suspect the ribbon is yellow, the bushes behind a nice deep green.', '2008-09-24 12:41:12.000000', NULL, 1),
(4972244, 723909, 30982, '<td valign="top">To me, either orange or yellow (orange given the title hint!).  Good closeup, pretty good composition though just a touch tight on the one side.  Can''t tell what it''s splashing into or onto, but that''s probably irrelevant.</td>', 'To me, either orange or yellow (orange given the title hint!).  Good closeup, pretty good composition though just a touch tight on the one side.  Can''t tell what it''s splashing into or onto, but that''s probably irrelevant.', '2008-09-24 12:42:24.000000', NULL, 1),
(4972246, 723048, 30982, '<td valign="top">A good choice for the challenge topic - definitely conveys color!  I think it could be just a tad lighter/brighter - a touch of levels or brightness/contrast perhaps.</td>', 'A good choice for the challenge topic - definitely conveys color!  I think it could be just a tad lighter/brighter - a touch of levels or brightness/contrast perhaps.', '2008-09-24 12:43:30.000000', NULL, 1),
(4972249, 724362, 30982, '<td valign="top">Even in B&amp;W this is very bright, very bold!  And yes, colorful.</td>', 'Even in B&W this is very bright, very bold!  And yes, colorful.', '2008-09-24 12:44:14.000000', NULL, 1),
(4972252, 724013, 30982, '<td valign="top">I like how the flame is pushing up against the top edge of the frame.  Almost looks as though it''s been constricted there!</td>', 'I like how the flame is pushing up against the top edge of the frame.  Almost looks as though it''s been constricted there!', '2008-09-24 12:44:43.000000', NULL, 1),
(4972257, 723480, 30982, '<td valign="top">The full details of the challenge (which I''m sure have been quoted to you by now) specify a black and white photograph.  That said, this is a good shot - lovely softness to the blooms.  Has just a touch of blue to it - not sure if that''s white balance or the environment at the time you shot it.</td>', 'The full details of the challenge (which I''m sure have been quoted to you by now) specify a black and white photograph.  That said, this is a good shot - lovely softness to the blooms.  Has just a touch of blue to it - not sure if that''s white balance or the environment at the time you shot it.', '2008-09-24 12:46:01.000000', NULL, 1),
