(4972765, 724462, 63499, '<td valign="top">This is a gorgeous b&amp;w flower! I love the contrast - the whites, the blacks and everything in between - the sharpness and how the flowers pops against the black background. While it doesn''t make me think of a particular color, it does give me the visualization of a light colored center with darker tips.</td>', 'This is a gorgeous b&w flower! I love the contrast - the whites, the blacks and everything in between - the sharpness and how the flowers pops against the black background. While it doesn''t make me think of a particular color, it does give me the visualization of a light colored center with darker tips.', '2008-09-24 15:04:31.000000', NULL, 1),
(4972767, 723993, 94265, '<td valign="top">Very funky, good model too.</td>', 'Very funky, good model too.', '2008-09-24 15:05:42.000000', NULL, 1),
(4972775, 723861, 94265, '<td valign="top">Haha I like this idea, nice composition.</td>', 'Haha I like this idea, nice composition.', '2008-09-24 15:08:47.000000', NULL, 1),
(4972779, 724242, 94265, '<td valign="top">Good crop and composition, just needs a bit more contrast.</td>', 'Good crop and composition, just needs a bit more contrast.', '2008-09-24 15:09:42.000000', NULL, 1),
(4972781, 724013, 94265, '<td valign="top">I don''t understand the title, either you uploaded the wrong photo or it''s a private joke! Good macro though, I like the focus.</td>', 'I don''t understand the title, either you uploaded the wrong photo or it''s a private joke! Good macro though, I like the focus.', '2008-09-24 15:10:52.000000', NULL, 1),
(4972782, 724377, 94265, '<td valign="top">Really good focus.</td>', 'Really good focus.', '2008-09-24 15:11:59.000000', NULL, 1),
(4972852, 723987, 36371, '<td valign="top">Very nice contrast and shadowing. 6</td>', 'Very nice contrast and shadowing. 6', '2008-09-24 16:00:06.000000', NULL, 1),
(4972863, 722637, 36371, '<td valign="top">Beautiful! Made me gasp! 10</td>', 'Beautiful! Made me gasp! 10', '2008-09-24 16:03:41.000000', NULL, 1),
(4972868, 723544, 75532, '<td valign="top">funny the only thing I can focus on in this mass confusion of people gathering, is the young man at the bottom center looking at the girl I like it :) 8 and yes I immediately see all the skin tones, and the blue jeans, and the red hats or w/e they were wearing</td>', 'funny the only thing I can focus on in this mass confusion of people gathering, is the young man at the bottom center looking at the girl I like it :) 8 and yes I immediately see all the skin tones, and the blue jeans, and the red hats or w/e they were wearing', '2008-09-24 16:08:10.000000', NULL, 1),
(4972869, 724358, 36999, '<td valign="top">great composition and lovely full tonal range from black to white and everything in between.</td>', 'great composition and lovely full tonal range from black to white and everything in between.', '2008-09-24 16:09:00.000000', NULL, 1),
(4972871, 723388, 36999, '<td valign="top">a wee bit more breathing room at the top would help, otherwise nice image.</td>', 'a wee bit more breathing room at the top would help, otherwise nice image.', '2008-09-24 16:10:12.000000', NULL, 1),
(4972873, 722958, 36999, '<td valign="top">the tonal range is flat and lopsided.  There is not much above middle grey.  LIghtening it and/or adding contrast would help lots.</td>', 'the tonal range is flat and lopsided.  There is not much above middle grey.  LIghtening it and/or adding contrast would help lots.', '2008-09-24 16:11:44.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
