(4972883, 724276, 36999, '<td valign="top">not a full tonal range....  missing the light greys and whites.  I like the subject, lots of fun reflections</td>', 'not a full tonal range....  missing the light greys and whites.  I like the subject, lots of fun reflections', '2008-09-24 16:16:17.000000', NULL, 1),
(4972884, 723843, 36999, '<td valign="top">nice full tonal range.  Not too crazy abuot the border, it''s a bit heavy for the rest of the image it seems</td>', 'nice full tonal range.  Not too crazy abuot the border, it''s a bit heavy for the rest of the image it seems', '2008-09-24 16:17:07.000000', NULL, 1),
(4972886, 724140, 36999, '<td valign="top">ha, love the title.  the image is too dark for a full tonal range.  using contrast or levels to get grya above middle grey and white would help alot.  a sharp image would also help a lot</td>', 'ha, love the title.  the image is too dark for a full tonal range.  using contrast or levels to get grya above middle grey and white would help alot.  a sharp image would also help a lot', '2008-09-24 16:19:16.000000', NULL, 1),
