(4972893, 724057, 36999, '<td valign="top">nice composition but not a full tonal range.  There is nothing here lighter than middle grey.  If you had the lights as well as the darks this image would rock.</td>', 'nice composition but not a full tonal range.  There is nothing here lighter than middle grey.  If you had the lights as well as the darks this image would rock.', '2008-09-24 16:21:05.000000', NULL, 1),
(4972896, 723140, 36999, '<td valign="top">nice tonal range and very well done pile of similar subjects.</td>', 'nice tonal range and very well done pile of similar subjects.', '2008-09-24 16:22:26.000000', NULL, 1),
(4972918, 724181, 87305, '<td valign="top">Nice frame..</td>', 'Nice frame..', '2008-09-24 16:42:11.000000', NULL, 1),
